using Godot;
using System;
using System.Linq;
using System.Collections.Generic;
using GArray=Godot.Collections.Array;
using Settings=Godot.Collections.Dictionary;
public partial class PhysicsSettingsOperations:RefCounted
{
    private readonly ActorDataOperations _data=new();private readonly ActorAnimationOperations _animation=new();private readonly GrowthPhysicsOperations _growth=new();private readonly Expression _equal=new();
    public PhysicsSettingsOperations(){_equal.Parse("a == b",new[]{"a","b"});}
    private static Variant Get(Settings values,string key,Variant fallback=default)=>values.TryGetValue(key,out var value)?value:fallback;
    private static Settings Values(Resource actor)=>actor.Get("values").AsGodotDictionary();private static string Type(Resource actor)=>actor.Get("type_id").AsString();private static Settings Physics(Resource actor)=>Get(Values(actor),"physics",new Settings()).VariantType==Variant.Type.Dictionary?Get(Values(actor),"physics",new Settings()).AsGodotDictionary():new Settings();
    public bool compatible(Resource? actor)=>actor!=null&&Type(actor)!="global_fog"&&Get(Values(actor),"position").VariantType==Variant.Type.Vector3&&Type(actor) is not ("world_environment" or "audio")&&!Type(actor).EndsWith("_2d",StringComparison.Ordinal);
    public Settings authored(Resource actor)
    {
        var result=GD.Load<GDScript>("res://scripts/actors/physics/physics_settings.gd").GetScriptConstantMap()["DEFAULTS"].AsGodotDictionary().Duplicate(true);var values=Values(actor);var physics=Physics(actor);result.Merge(physics,true);string type=Type(actor);if(type=="environment_asset"){var path=Get(values,"environment_path");result["enabled"]=result["enabled"].AsBool()&&path.VariantType==Variant.Type.String&&path.AsString().Length>0;}if(type=="fog_volume"){result["type"]=9;result["enabled"]=Get(values,"fog_motion_mode",0).AsInt32()>=2&&Get(physics,"enabled",true).AsBool();if(!physics.ContainsKey("steps"))result["steps"]=30;}if(type=="fluid")result["type"]=6;if(type=="powder")result["type"]=7;if(_growth.data(actor)!=null)result["type"]=8;if(Get(values,"destruction_enabled",false).AsBool()&&!result["enabled"].AsBool()){result["enabled"]=true;result["body_mode"]=2;}if(Get(values,"structure_enabled",false).AsBool()){result["enabled"]=true;result["type"]=0;result["body_mode"]=Get(values,"structure_role",0).AsInt32();}return result;
    }
    public Settings sample(Resource actor,double time)
    {
        var result=authored(actor);var sampled=new HashSet<string>();foreach(var value in actor.Get("animation_tracks").AsGodotArray()){var path=value.As<Resource>().Get("path").AsStringArray();if(path.Length<2||path[0]!="physics"||!sampled.Add(string.Join(" / ",path)))continue;var nested=path.Skip(1).ToArray();set_nested(result,nested,_animation.sampled_value(actor,path,time,get_nested(result,nested)));}foreach(var value in actor.Get("animation_previews").AsGodotDictionary().Values){var preview=value.AsGodotDictionary();var path=preview["path"].AsStringArray();if(path.Length>=2&&path[0]=="physics")set_nested(result,path.Skip(1).ToArray(),preview["value"]);}string type=Type(actor);var values=Values(actor);var physics=Physics(actor);if(type=="fluid")result["type"]=6;if(type=="powder"){result["type"]=7;result["enabled"]=result["enabled"].AsBool()&&_animation.sampled_value(actor,new[]{"powder_enabled"},time,Get(values,"powder_enabled",true)).AsBool();}if(_data.animation_track(actor,new[]{"destruction_enabled"})!=null&&!Get(physics,"enabled",false).AsBool()){result["enabled"]=true;result["body_mode"]=2;}if(_animation.sampled_value(actor,new[]{"structure_enabled"},time,Get(values,"structure_enabled",false)).AsBool()){result["enabled"]=true;result["type"]=0;result["body_mode"]=_animation.sampled_value(actor,new[]{"structure_role"},time,Get(values,"structure_role",0)).AsInt32();}else if((_data.get_value(actor,"structure_enabled",false).AsBool()||_data.animation_track(actor,new[]{"structure_enabled"})!=null)&&!Get(physics,"enabled",false).AsBool()&&!_data.get_value(actor,"destruction_enabled",false).AsBool())result["enabled"]=false;if(_growth.data(actor)!=null)result["type"]=8;return result;
    }
    public Variant get_nested(Settings values,string[] path){var value=Variant.From(values);foreach(string key in path){if(value.VariantType!=Variant.Type.Dictionary)return default;value=Get(value.AsGodotDictionary(),key);}return value;}
    public void set_nested(Settings values,string[] path,Variant value){if(path.Length==0)return;var target=values;for(int i=0;i<path.Length-1;i++){var child=Get(target,path[i],new Settings());var copy=child.VariantType==Variant.Type.Dictionary?child.AsGodotDictionary().Duplicate(true):new Settings();target[path[i]]=copy;target=copy;}target[path[^1]]=_data.copy_value(value);}
    public bool configured(Resource actor){if(!compatible(actor))return false;if(authored(actor)["enabled"].AsBool())return true;return _data.animation_track(actor,new[]{"destruction_enabled"})!=null||_data.animation_track(actor,new[]{"structure_enabled"})!=null||_data.animation_track(actor,new[]{"physics","enabled"})!=null;}
    public void edit(RefCounted model,Resource actor,string key,Variant value){var path=new[]{"physics",key};if(_data.animation_track(actor,path)!=null){model.Call("commit_animation_value",actor,path,value);return;}var before=_data.copy_value(Get(Values(actor),"physics",new Settings())).AsGodotDictionary();var after=authored(actor);after[key]=_data.copy_value(value);if(_equal.Execute(new GArray{before,after}).AsBool())return;var history=model.Get("history").As<UndoRedo>();var action=new PhysicsSettingsHistoryAction(model,actor,before,after);history.CreateAction("Physics: "+key.Capitalize());history.AddDoMethod(new Callable(action,nameof(PhysicsSettingsHistoryAction.restore_after)));history.AddUndoMethod(new Callable(action,nameof(PhysicsSettingsHistoryAction.restore_before)));history.AddDoReference(action);history.CommitAction();}
    public void assign(RefCounted model,Resource actor,Settings values){Values(actor)[new StringName("physics")]=_data.copy_value(values);actor.Get("animation_previews").AsGodotDictionary().Clear();actor.EmitChanged();model.EmitSignal("changed");}
    private static string Slice(string source,string separator,int index){var parts=source.Split(separator,StringSplitOptions.None);return index<parts.Length?parts[index]:"";}
    public Settings remap(Settings values,Settings ids)
    {
        var result=values.Duplicate(true);foreach(string key in new[]{"attachment","end_actor"})if(result.ContainsKey(key))result[key]=Get(ids,result[key].AsString(),result[key]);foreach(var value in Get(result,"pins",new GArray()).AsGodotArray()){var pin=value.AsGodotDictionary();pin["actor"]=Get(ids,Get(pin,"actor","").AsString(),Get(pin,"actor",""));}var bake=Get(result,"bake",new Settings()).AsGodotDictionary();var snapshots=Get(bake,"frames",new GArray()).AsGodotArray().Duplicate();var frozen=Get(result,"frozen",new Settings()).AsGodotDictionary();if(Get(frozen,"state").VariantType==Variant.Type.Dictionary)snapshots.Add(frozen["state"]);
        foreach(var value in snapshots){var state=value.AsGodotDictionary();foreach(var item in Get(state,"destruction_fragments",new GArray()).AsGodotArray()){var fragment=item.AsGodotDictionary();string id=fragment["id"].AsString(),source=Slice(id,":fragment:",0);if(ids.ContainsKey(source))fragment["id"]=ids[source].AsString()+":fragment:"+Slice(id,":fragment:",1);}foreach(var item in Get(state,"destruction_events",new GArray()).AsGodotArray()){var entry=item.AsGodotDictionary();entry["source_actor"]=Get(ids,Get(entry,"source_actor","").AsString(),Get(entry,"source_actor",""));}if(state.TryGetValue("structural",out var structure)){var data=structure.AsGodotDictionary();string island=Get(data,"island","").AsString();data["island"]=Get(ids,island,island);}foreach(var item in Get(state,"powder_deposits",new Settings()).AsGodotDictionary().Values){var deposit=item.AsGodotDictionary();deposit["actor"]=Get(ids,deposit["actor"].AsString(),deposit["actor"]);string proxy=Get(deposit,"proxy","").AsString();if(proxy.Contains(":p",StringComparison.Ordinal)){string old=Slice(proxy,":p",0);deposit["proxy"]=Get(ids,old,old).AsString()+":p"+Slice(proxy,":p",1);}}if(!state.ContainsKey("powder_bonds"))continue;var bonds=new Settings();foreach(var item in state["powder_bonds"].AsGodotDictionary().Values){var bond=item.AsGodotDictionary();bond["actor"]=Get(ids,bond["actor"].AsString(),bond["actor"]);bonds[bond["a"].ToString()+"|"+bond["actor"].AsString()+"|"+bond["b"].ToString()]=bond;}state["powder_bonds"]=bonds;}
        if(ids.Count>0&&bake.Count>0){if(Get(bake,"portable",false).AsBool()){var mapped=new Settings();var previous=Get(bake,"portable_ids",new Settings()).AsGodotDictionary();if(previous.Count==0)foreach(var entry in ids)mapped[entry.Key]=entry.Value;else foreach(var entry in previous)mapped[entry.Key]=Get(ids,entry.Value.AsString(),entry.Value);bake["portable_ids"]=mapped;}else bake["signature"]="";}return result;
    }
    public void pin(Control editor,Resource actor,int index,Vector3 position,bool remove){var config=authored(actor);var pins=config["pins"].AsGodotArray().Duplicate(true);for(int i=pins.Count-1;i>=0;i--)if(Get(pins[i].AsGodotDictionary(),"point",-1).AsInt32()==index)pins.RemoveAt(i);if(!remove){string target=config["attachment"].AsString(),bone=config["attachment_bone"].AsString();var offset=position;if(target.Length>0)offset=editor.Get("physics").AsGodotObject().Call("bone_world",target,bone,editor.Get("canvas").AsGodotObject().Get("playhead")).AsTransform3D().AffineInverse()*position;pins.Add(new Settings{["point"]=index,["actor"]=target,["bone"]=bone,["follow"]=target.Length>0,["offset"]=offset,["world"]=position});}edit(editor.Get("model").As<RefCounted>(),actor,"pins",pins);}
}
